import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    static long power(long base, long exp) {
        long result = 1;
        for (int i = 0; i < exp; ++i) {
            result = (result * base) % MOD;
        }
        return result;
    }

    static long compute(long p, long k) {
        if (k <= 1) {
            return power(p, p - 1 + k);
        }
        int order = 1;
        long current = k;
        while (current != 1) {
            current = (current * k) % p;
            ++order;
        }
        return power(p, (p - 1) / order);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        System.out.println(compute(p, k));
        scanner.close();
    }
}
